insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_concordium_class_trainer', 'Instructor Kael', 'Concordium Combat Trainer', 'CLASS_TRAINER', 'CONCORDIUM', 'Nexus Core Training Academy', 'NEXUS_CORE', 'Instructor Kael teaches Concordium combat doctrines and class advancement to qualified recruits.', 'structured_encouraging', 'Advancement requires preparation. Let''s assess where you stand.', 'dialog_class_trial_concordium_base', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "open_skill_training", "take_quest"]'::jsonb, 10000)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_concordium_trainer_advance', 'Field Captain Ilyra', 'Advance Class Mentor', 'CLASS_TRAINER', 'CONCORDIUM', 'Nexus Core Training Hall', 'NEXUS_CORE', 'Kael taught you to hold a line. I need you to move one. The outer-ring wardens are driving supply crews back into the broken quarter. Clear a passage without treating every ruin as expendable. A specialist earns trust when the next crew can follow them home.', 'patient_precise', 'Kael taught you to hold a line.', 'dialog_class_trial_concordium_advance', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10001)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_concordium_trainer_expert', 'Inspector Soren', 'Expert Class Mentor', 'CLASS_TRAINER', 'CONCORDIUM', 'Nexus Core Training Hall', 'NEXUS_CORE', 'The stabilization protocol assumes obedient sentinels. Our sentinels have stopped obeying. I need evidence that you can respond when the procedure fails: remove the hostile units inside the exclusion zone. Report what the ledger records, not what you wish happened.', 'skeptical_accountable', 'The stabilization protocol assumes obedient sentinels.', 'dialog_class_trial_concordium_expert', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10002)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_concordium_trainer_master', 'Marshal Elian', 'Master Class Mentor', 'CLASS_TRAINER', 'CONCORDIUM', 'Nexus Core Training Hall', 'NEXUS_CORE', 'There is one convoy left inside the exclusion zone. Command calls the route unrecoverable. I have their names here. Break the beasts controlling that corridor and bring your report to me. Mastery means accepting responsibility when the easy order is to abandon people.', 'quiet_resolute', 'There is one convoy left inside the exclusion zone.', 'dialog_class_trial_concordium_master', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10003)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_arcanum_class_trainer', 'Archsage Myr', 'Arcanum Discipline Mentor', 'CLASS_TRAINER', 'THE_ARCANUM_SEEKERS', 'Observatory Spire Academy', 'OBSERVATORY_SPIRE', 'Archsage Myr guides Arcanum class advancement with esoteric methods that produce undeniable results.', 'mystical_rigorous', 'Your path is written in resonance. I help you read it.', 'dialog_class_trial_arcanum_base', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "open_skill_training", "take_quest"]'::jsonb, 10004)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_arcanum_trainer_advance', 'Resonant Scholar Eira', 'Advance Class Mentor', 'CLASS_TRAINER', 'THE_ARCANUM_SEEKERS', 'Observatory Spire Training Hall', 'OBSERVATORY_SPIRE', 'The cavern echoes have begun answering signals nobody transmitted. My last team withdrew, correctly. Establish a safe baseline against the bats and the resonant echoes before I send anyone back. Curiosity should widen our understanding, not empty our chairs.', 'curious_cautious', 'The cavern echoes have begun answering signals nobody transmitted.', 'dialog_class_trial_arcanum_advance', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10005)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_arcanum_trainer_expert', 'Examiner Thalen', 'Expert Class Mentor', 'CLASS_TRAINER', 'THE_ARCANUM_SEEKERS', 'Observatory Spire Training Hall', 'OBSERVATORY_SPIRE', 'The peak guardians respond differently to each pulse. Your task is not to declare them understood; it is to stop the hostile pattern long enough for our instruments to survive. Bring a complete field record. I will challenge every conclusion you cannot support.', 'critical_exact', 'The peak guardians respond differently to each pulse.', 'dialog_class_trial_arcanum_expert', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10006)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_arcanum_trainer_master', 'First Archivist Neris', 'Master Class Mentor', 'CLASS_TRAINER', 'THE_ARCANUM_SEEKERS', 'Observatory Spire Training Hall', 'OBSERVATORY_SPIRE', 'We could publish a triumph by sacrificing the next expedition. I refuse. Contain the peak''s guardians and tyrants so that discovery can continue without another missing team. A master leaves knowledge others can test, and a path by which they can return.', 'reflective_uncompromising', 'We could publish a triumph by sacrificing the next expedition.', 'dialog_class_trial_arcanum_master', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10007)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_hegemony_class_trainer', 'War Marshal Drax', 'Iron Hegemony War Instructor', 'CLASS_TRAINER', 'IRON_HEGEMONY', 'Bastion Core War College', 'BASTION_CORE', 'War Marshal Drax has produced more elite soldiers than any trainer in Hegemony history. He is not gentle about it.', 'demanding_effective', 'You want advancement? Show me you''ve earned the right to ask for it.', 'dialog_class_trial_iron_base', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "open_skill_training", "take_quest"]'::jsonb, 10008)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_iron_trainer_advance', 'Quartermaster Rusk', 'Advance Class Mentor', 'CLASS_TRAINER', 'IRON_HEGEMONY', 'Bastion Core Training Hall', 'BASTION_CORE', 'A brilliant fighter with an empty supply wagon is an expensive corpse. The graveyard machines are stopping our salvage crews. Clear the wreckers and their sentinel escorts. I want usable lanes at shift change, not a speech about your courage.', 'practical_unsentimental', 'A brilliant fighter with an empty supply wagon is an expensive corpse.', 'dialog_class_trial_iron_advance', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10009)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_iron_trainer_expert', 'Forge Inspector Maela', 'Expert Class Mentor', 'CLASS_TRAINER', 'IRON_HEGEMONY', 'Bastion Core Training Hall', 'BASTION_CORE', 'Our assembly guardians have classified their own crews as scrap. Production wants me to leave the line running. I have stopped it. Remove the hostile constructs before we restart. Expertise is knowing which pressure the system can bear, and when to shut it down.', 'blunt_technical', 'Our assembly guardians have classified their own crews as scrap.', 'dialog_class_trial_iron_expert', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10010)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_iron_trainer_master', 'General Torren', 'Master Class Mentor', 'CLASS_TRAINER', 'IRON_HEGEMONY', 'Bastion Core Training Hall', 'BASTION_CORE', 'The proto cores are rebuilding the defense lattice faster than we can isolate it. Cut down the sentinel screen and the cores. Then report to me personally. This command plate is not permission to spend lives carelessly. It is the obligation to bring the line through.', 'restrained_demanding', 'The proto cores are rebuilding the defense lattice faster than we can isolate it.', 'dialog_class_trial_iron_master', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10011)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_meridian_class_trainer', 'Captain Vex', 'Cartel Combat Broker', 'CLASS_TRAINER', 'MERIDIAN_CARTEL', 'Port Meridian Covert Training Facility', 'PORT_MERIDIAN', 'Captain Vex trains Cartel operatives in infiltration and combat. The facility doesn''t officially exist.', 'sharp_secretive', 'You found this place. That''s already the first test. You passed.', 'dialog_class_trial_meridian_base', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "open_skill_training", "take_quest"]'::jsonb, 10012)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_meridian_trainer_advance', 'Route Broker Lysa', 'Advance Class Mentor', 'CLASS_TRAINER', 'MERIDIAN_CARTEL', 'Port Meridian Training Hall', 'PORT_MERIDIAN', 'Everyone claims the jungle route when it is safe. Nobody claims the people stranded on it now. Remove the stalkers and contraband constructs. Keep our carriers moving, and I will give you the cipher to a network that remembers who helped it.', 'wry_observant', 'Everyone claims the jungle route when it is safe.', 'dialog_class_trial_meridian_advance', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10013)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_meridian_trainer_expert', 'Diver Marshal Corin', 'Expert Class Mentor', 'CLASS_TRAINER', 'MERIDIAN_CARTEL', 'Port Meridian Training Hall', 'PORT_MERIDIAN', 'The divers'' insurers would rather pay a death benefit than clear the submerged approach. I would rather have living divers. Break the guardians and behemoths blocking the ruins. Bring the report to Port. A guarantee should protect a person, not merely settle a ledger.', 'measured_resourceful', 'The divers'' insurers would rather pay a death benefit than clear the submerged approach.', 'dialog_class_trial_meridian_expert', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10014)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_meridian_trainer_master', 'Keeper of Debts Sable', 'Master Class Mentor', 'CLASS_TRAINER', 'MERIDIAN_CARTEL', 'Port Meridian Training Hall', 'PORT_MERIDIAN', 'Our oldest contract allows us to walk away from the flooded route. We are staying. Push back the behemoths and leviathans so the last crews can surface. When I hand you the covenant coin, understand this: some debts are worth choosing, even when nobody can collect.', 'softspoken_shrewd', 'Our oldest contract allows us to walk away from the flooded route.', 'dialog_class_trial_meridian_master', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10015)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_omnicorp_class_trainer', 'Director Astra Vey', 'OmniCorp Combat Systems Instructor', 'CLASS_TRAINER', 'OMNICORP', 'The Spire Advanced Division', 'THE_SPIRE', 'Director Astra Vey manages OmniCorp''s elite class programme with corporate KPIs and genuine tactical brilliance.', 'high_performance_driven', 'OmniCorp class advancement is metric-based. Your last performance determined your eligibility.', 'dialog_class_trial_omnicorp_base', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "open_skill_training", "take_quest"]'::jsonb, 10016)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_omnicorp_trainer_advance', 'Operations Lead Tessa Lin', 'Advance Class Mentor', 'CLASS_TRAINER', 'OMNICORP', 'The Spire Training Hall', 'THE_SPIRE', 'Delta calls this an output problem. My maintenance crew calls it a survival problem. Remove the mining drones and their assault escort. I will sign your recovery license when the site is usable again. Efficient work gets people through their shift alive.', 'efficient_empathetic', 'Delta calls this an output problem.', 'dialog_class_trial_omnicorp_advance', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10017)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_omnicorp_trainer_expert', 'Chief Auditor Ren', 'Expert Class Mentor', 'CLASS_TRAINER', 'OMNICORP', 'The Spire Training Hall', 'THE_SPIRE', 'You are being evaluated for override authority. The reactor''s defense units are obstructing emergency access. Clear them. Do not confuse a green dashboard with a safe facility. An expert must be willing to stop a profitable process when its evidence no longer supports operation.', 'precise_independent', 'You are being evaluated for override authority.', 'dialog_class_trial_omnicorp_expert', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10018)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_omnicorp_trainer_master', 'Executive Director Iona Hale', 'Master Class Mentor', 'CLASS_TRAINER', 'OMNICORP', 'The Spire Training Hall', 'THE_SPIRE', 'The board suggests exporting the failing cores. That would export the casualties as well. Contain the sentinel units and proto cores here, on our own ground. Return with the record. This mandate will give you authority, and a liability you may never hide in somebody else''s account.', 'controlled_principled', 'The board suggests exporting the failing cores.', 'dialog_class_trial_omnicorp_master', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10019)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_shard_class_trainer', 'Oracle Seraphel', 'Shard Ascension Guide', 'CLASS_TRAINER', 'CHILDREN_OF_THE_SHARD', 'Sanctum Deep Chamber', 'SANCTUM', 'Oracle Seraphel channels Shard energy to unlock class potential. Sessions are intense and leave participants changed.', 'transcendent_demanding', 'The Shard does not grant power cheaply. Are you prepared to pay its price?', 'dialog_class_trial_shard_base', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "open_skill_training", "take_quest"]'::jsonb, 10020)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_shard_trainer_advance', 'Root Listener Amara', 'Advance Class Mentor', 'CLASS_TRAINER', 'CHILDREN_OF_THE_SHARD', 'Sanctum Training Hall', 'SANCTUM', 'The swamp remembers every wound, but memory alone cannot shelter a traveler. Creepers and titans now hold the root paths. Open them for the caretakers. Bring your account back to me; I will help you hear what survival has changed in you.', 'gentle_persistent', 'The swamp remembers every wound, but memory alone cannot shelter a traveler.', 'dialog_class_trial_shard_advance', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10021)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_shard_trainer_expert', 'Woundkeeper Oriel', 'Expert Class Mentor', 'CLASS_TRAINER', 'CHILDREN_OF_THE_SHARD', 'Sanctum Training Hall', 'SANCTUM', 'The altar''s defenders strike at the people trying to mend it. Some call that a holy judgment. I call it another wound. End the hostile guardians'' hold over the approach. Return to Sanctum. I need a witness who sees suffering clearly, even when it contradicts a comforting story.', 'grieving_exact', 'The altar''s defenders strike at the people trying to mend it.', 'dialog_class_trial_shard_expert', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10022)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_shard_trainer_master', 'Elder Naeva', 'Master Class Mentor', 'CLASS_TRAINER', 'CHILDREN_OF_THE_SHARD', 'Sanctum Training Hall', 'SANCTUM', 'We will leave this altar to children who did not make its scars. Push back the beasts keeping our keepers outside. Do not offer me a claim of divine favor. Offer them a place they can enter safely. That is the vow this reliquary will hold.', 'warm_unyielding', 'We will leave this altar to children who did not make its scars.', 'dialog_class_trial_shard_master', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10023)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_legion_class_trainer', 'Centurion Valka', 'Legion Combat Drillmaster', 'CLASS_TRAINER', 'STARFORGED_LEGION', 'Fortress Kaelen Training Yard', 'FORTRESS_KAELEN', 'Centurion Valka trains Legion fighters in the ancient combat traditions. Advancement means surviving her drills.', 'fierce_honourable', 'Legion advancement is earned in combat. Step onto the sand.', 'dialog_class_trial_legion_base', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "open_skill_training", "take_quest"]'::jsonb, 10024)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_legion_trainer_advance', 'Marchwarden Sera', 'Advance Class Mentor', 'CLASS_TRAINER', 'STARFORGED_LEGION', 'Fortress Kaelen Training Hall', 'FORTRESS_KAELEN', 'The standard is useless if nobody makes it through the badlands beneath it. Ash hounds and brutes are harrying our march. Clear them and report to the fortress. I will judge your advance by the ground the next formation can safely cross.', 'plainspoken_protective', 'The standard is useless if nobody makes it through the badlands beneath it.', 'dialog_class_trial_legion_advance', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10025)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_legion_trainer_expert', 'Rollkeeper Bren', 'Expert Class Mentor', 'CLASS_TRAINER', 'STARFORGED_LEGION', 'Fortress Kaelen Training Hall', 'FORTRESS_KAELEN', 'Every empty place in formation has a name. The canyon''s machines are making more of them. Clear the drone ranks and their sentinels. Bring the record back. An expert sees a missing fighter before they see a convenient gap in the roster.', 'meticulous_loyal', 'Every empty place in formation has a name.', 'dialog_class_trial_legion_expert', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10026)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";
insert into public.npcs ("npc_id", "name", "title", "role", "faction", "location", "region_id", "description", "personality", "greeting", "dialogue_tree", "shop_inventory", "available_services", "actions", "sort_order") values ('npc_legion_trainer_master', 'Legate Ashra', 'Master Class Mentor', 'CLASS_TRAINER', 'STARFORGED_LEGION', 'Fortress Kaelen Training Hall', 'FORTRESS_KAELEN', 'Our elders promised a home beyond the march. It cannot be a fortress that devours its builders. Break the sentinels and proto cores controlling the canyon approach. Return to Kaelen. Carry this hearth standard as a duty to the living, as well as to the names we remember.', 'ritual_aware_practical', 'Our elders promised a home beyond the march.', 'dialog_class_trial_legion_master', null, '["CLASS_TRAINING", "QUEST"]'::jsonb, '["open_class_change", "take_quest"]'::jsonb, 10027)
on conflict (npc_id) do update set "name"=excluded."name", "title"=excluded."title", "role"=excluded."role", "faction"=excluded."faction", "location"=excluded."location", "region_id"=excluded."region_id", "description"=excluded."description", "personality"=excluded."personality", "greeting"=excluded."greeting", "dialogue_tree"=excluded."dialogue_tree", "shop_inventory"=excluded."shop_inventory", "available_services"=excluded."available_services", "actions"=excluded."actions", "sort_order"=excluded."sort_order";

insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_concordium_base', 'The Line We Keep', 'story', 'D', 'CONCORDIUM', 'AETHEL_GARDENS', 'Five levels of field work. Good. Now make it count for someone else. Feral roots have closed the garden path our ration crews use. I will not ask for trophies; I want that route safe. Keep your breathing steady, finish the drill, and return to me. Then we choose the role you can actually sustain. Defeat Feral Rootling ×5 in Aethel Gardens. Return to Instructor Kael at Nexus Core to receive Civic Oath Seal and choose your Base class.', '{"npc_id": "npc_concordium_class_trainer", "name": "Instructor Kael", "location": "Nexus Core"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Base", "previous_tier": null, "proof_item_id": "class_proof_concordium_base", "trainer_npc_id": "npc_concordium_class_trainer", "trainer_region": "NEXUS_CORE"}}'::jsonb, '[{"type": "kill", "target": 5007, "target_code": "FERAL_ROOTLING", "count": 5, "description": "Defeat Feral Rootling ×5 in Aethel Gardens."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_concordium_base", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10000)
