insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_concordium_advance', 'A Route for Everyone', 'story', 'C', 'CONCORDIUM', 'CRADLE_OUTER_RING', 'Kael taught you to hold a line. I need you to move one. The outer-ring wardens are driving supply crews back into the broken quarter. Clear a passage without treating every ruin as expendable. A specialist earns trust when the next crew can follow them home. Defeat Cradle Fragment Beast ×8 in Cradle Outer Ring. Defeat Cradle Warden ×2 in Cradle Outer Ring. Return to Field Captain Ilyra at Nexus Core to receive Routekeeper Warrant and choose your Advance class.', '{"npc_id": "npc_concordium_trainer_advance", "name": "Field Captain Ilyra", "location": "Nexus Core"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Advance", "previous_tier": "Base", "proof_item_id": "class_proof_concordium_advance", "trainer_npc_id": "npc_concordium_trainer_advance", "trainer_region": "NEXUS_CORE"}}'::jsonb, '[{"type": "kill", "target": 5116, "target_code": "CRADLE_FRAGMENT_BEAST", "count": 8, "description": "Defeat Cradle Fragment Beast ×8 in Cradle Outer Ring."}, {"type": "kill", "target": 5115, "target_code": "CRADLE_WARDEN", "count": 2, "description": "Defeat Cradle Warden ×2 in Cradle Outer Ring."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_concordium_advance", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10001)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_concordium_expert', 'Protocol Under Pressure', 'story', 'B', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'The stabilization protocol assumes obedient sentinels. Our sentinels have stopped obeying. I need evidence that you can respond when the procedure fails: remove the hostile units inside the exclusion zone. Report what the ledger records, not what you wish happened. Defeat Cradle Sentinel ×10 in Inner Cradle Exclusion. Defeat Cradle Purifier ×4 in Inner Cradle Exclusion. Return to Inspector Soren at Nexus Core to receive Cradle Stabilization Charter and choose your Expert class.', '{"npc_id": "npc_concordium_trainer_expert", "name": "Inspector Soren", "location": "Nexus Core"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Expert", "previous_tier": "Advance", "proof_item_id": "class_proof_concordium_expert", "trainer_npc_id": "npc_concordium_trainer_expert", "trainer_region": "NEXUS_CORE"}}'::jsonb, '[{"type": "kill", "target": 5201, "target_code": "CRADLE_SENTINEL", "count": 10, "description": "Defeat Cradle Sentinel ×10 in Inner Cradle Exclusion."}, {"type": "kill", "target": 5202, "target_code": "CRADLE_PURIFIER", "count": 4, "description": "Defeat Cradle Purifier ×4 in Inner Cradle Exclusion."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_concordium_expert", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10002)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_concordium_master', 'The Last Civilian Convoy', 'story', 'A', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'There is one convoy left inside the exclusion zone. Command calls the route unrecoverable. I have their names here. Break the beasts controlling that corridor and bring your report to me. Mastery means accepting responsibility when the easy order is to abandon people. Defeat Arcane Rift Beast ×16 in Inner Cradle Exclusion. Defeat Cradle Void Titanling ×6 in Inner Cradle Exclusion. Return to Marshal Elian at Nexus Core to receive Concordium Steward Sigil and choose your Master class.', '{"npc_id": "npc_concordium_trainer_master", "name": "Marshal Elian", "location": "Nexus Core"}'::jsonb, '{"min_level": 60, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Master", "previous_tier": "Expert", "proof_item_id": "class_proof_concordium_master", "trainer_npc_id": "npc_concordium_trainer_master", "trainer_region": "NEXUS_CORE"}}'::jsonb, '[{"type": "kill", "target": 5203, "target_code": "ARCANE_RIFT_BEAST", "count": 16, "description": "Defeat Arcane Rift Beast ×16 in Inner Cradle Exclusion."}, {"type": "kill", "target": 50052, "target_code": "CRADLE_VOID_TITANLING", "count": 6, "description": "Defeat Cradle Void Titanling ×6 in Inner Cradle Exclusion."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_concordium_master", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10003)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_arcanum_base', 'An Observation Before an Oath', 'story', 'D', 'THE_ARCANUM_SEEKERS', 'CRYSTAL_SLOPE', 'A class is a hypothesis about what you might become. Do not mistake it for proof. Wild Mushrooms are interrupting our slope readings; confront them and let the ledger record the results. Return with observations. I can teach a promising mind. I cannot teach a mind that invents its evidence. Defeat Wild Mushroom ×5 in Crystal Slope. Return to Archsage Myr at Observatory Spire to receive Resonance Thesis Prism and choose your Base class.', '{"npc_id": "npc_arcanum_class_trainer", "name": "Archsage Myr", "location": "Observatory Spire"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Base", "previous_tier": null, "proof_item_id": "class_proof_arcanum_base", "trainer_npc_id": "npc_arcanum_class_trainer", "trainer_region": "OBSERVATORY_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 5004, "target_code": "WILD_MUSHROOM", "count": 5, "description": "Defeat Wild Mushroom ×5 in Crystal Slope."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_arcanum_base", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10004)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_arcanum_advance', 'The Echo That Answers', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'The cavern echoes have begun answering signals nobody transmitted. My last team withdrew, correctly. Establish a safe baseline against the bats and the resonant echoes before I send anyone back. Curiosity should widen our understanding, not empty our chairs. Defeat Resonance Bat ×8 in Resonance Caverns. Defeat Resonance Echo ×2 in Resonance Caverns. Return to Resonant Scholar Eira at Observatory Spire to receive Echo Calibration Lens and choose your Advance class.', '{"npc_id": "npc_arcanum_trainer_advance", "name": "Resonant Scholar Eira", "location": "Observatory Spire"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Advance", "previous_tier": "Base", "proof_item_id": "class_proof_arcanum_advance", "trainer_npc_id": "npc_arcanum_trainer_advance", "trainer_region": "OBSERVATORY_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 5125, "target_code": "RESONANCE_BAT", "count": 8, "description": "Defeat Resonance Bat ×8 in Resonance Caverns."}, {"type": "kill", "target": 50015, "target_code": "RESONANCE_ECHO", "count": 2, "description": "Defeat Resonance Echo ×2 in Resonance Caverns."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_arcanum_advance", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10005)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_arcanum_expert', 'A Hypothesis with Teeth', 'story', 'B', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'The peak guardians respond differently to each pulse. Your task is not to declare them understood; it is to stop the hostile pattern long enough for our instruments to survive. Bring a complete field record. I will challenge every conclusion you cannot support. Defeat Shard Pulse Sentinel ×10 in Shard Pulse Peak. Defeat Shard Pulse Guardian ×4 in Shard Pulse Peak. Return to Examiner Thalen at Observatory Spire to receive Peer Witness Crystal and choose your Expert class.', '{"npc_id": "npc_arcanum_trainer_expert", "name": "Examiner Thalen", "location": "Observatory Spire"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Expert", "previous_tier": "Advance", "proof_item_id": "class_proof_arcanum_expert", "trainer_npc_id": "npc_arcanum_trainer_expert", "trainer_region": "OBSERVATORY_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 50053, "target_code": "SHARD_PULSE_SENTINEL", "count": 10, "description": "Defeat Shard Pulse Sentinel ×10 in Shard Pulse Peak."}, {"type": "kill", "target": 50054, "target_code": "SHARD_PULSE_GUARDIAN", "count": 4, "description": "Defeat Shard Pulse Guardian ×4 in Shard Pulse Peak."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_arcanum_expert", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10006)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_arcanum_master', 'Knowledge Worth Returning With', 'story', 'A', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'We could publish a triumph by sacrificing the next expedition. I refuse. Contain the peak''s guardians and tyrants so that discovery can continue without another missing team. A master leaves knowledge others can test, and a path by which they can return. Defeat Shard Pulse Guardian ×16 in Shard Pulse Peak. Defeat Shard Pulse Tyrant ×6 in Shard Pulse Peak. Return to First Archivist Neris at Observatory Spire to receive Arcanum Living Codex and choose your Master class.', '{"npc_id": "npc_arcanum_trainer_master", "name": "First Archivist Neris", "location": "Observatory Spire"}'::jsonb, '{"min_level": 60, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Master", "previous_tier": "Expert", "proof_item_id": "class_proof_arcanum_master", "trainer_npc_id": "npc_arcanum_trainer_master", "trainer_region": "OBSERVATORY_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 50054, "target_code": "SHARD_PULSE_GUARDIAN", "count": 16, "description": "Defeat Shard Pulse Guardian ×16 in Shard Pulse Peak."}, {"type": "kill", "target": 50055, "target_code": "SHARD_PULSE_TYRANT", "count": 6, "description": "Defeat Shard Pulse Tyrant ×6 in Shard Pulse Peak."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_arcanum_master", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10007)
