insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_iron_base', 'Steel Before Rank', 'story', 'D', 'IRON_HEGEMONY', 'SCRAP_FIELD', 'You have survived long enough to train properly. Scrap drones are tearing up the recovery lanes. Shut them down. No borrowed commendation, no purchased rank. Finish the work, return to Bastion, and I will put a tempered rivet in your hand. What you do next is your choice. Defeat Scrap Drone ×5 in Scrap Field. Return to War Marshal Drax at Bastion Core to receive Tempered Service Rivet and choose your Base class.', '{"npc_id": "npc_hegemony_class_trainer", "name": "War Marshal Drax", "location": "Bastion Core"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Base", "previous_tier": null, "proof_item_id": "class_proof_iron_base", "trainer_npc_id": "npc_hegemony_class_trainer", "trainer_region": "BASTION_CORE"}}'::jsonb, '[{"type": "kill", "target": 50012, "target_code": "SCRAP_DRONE", "count": 5, "description": "Defeat Scrap Drone ×5 in Scrap Field."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_iron_base", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10008)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_iron_advance', 'Keep the Supply Line', 'story', 'C', 'IRON_HEGEMONY', 'WAR_MACHINE_GRAVEYARD', 'A brilliant fighter with an empty supply wagon is an expensive corpse. The graveyard machines are stopping our salvage crews. Clear the wreckers and their sentinel escorts. I want usable lanes at shift change, not a speech about your courage. Defeat War Machine Wrecker ×8 in War Machine Graveyard. Defeat War Machine Sentinel ×2 in War Machine Graveyard. Return to Quartermaster Rusk at Bastion Core to receive Supplyline Iron Writ and choose your Advance class.', '{"npc_id": "npc_iron_trainer_advance", "name": "Quartermaster Rusk", "location": "Bastion Core"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Advance", "previous_tier": "Base", "proof_item_id": "class_proof_iron_advance", "trainer_npc_id": "npc_iron_trainer_advance", "trainer_region": "BASTION_CORE"}}'::jsonb, '[{"type": "kill", "target": 5140, "target_code": "WAR_MACHINE_WRECKER", "count": 8, "description": "Defeat War Machine Wrecker ×8 in War Machine Graveyard."}, {"type": "kill", "target": 5142, "target_code": "WAR_MACHINE_SENTINEL", "count": 2, "description": "Defeat War Machine Sentinel ×2 in War Machine Graveyard."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_iron_advance", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10009)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_iron_expert', 'When the Forge Turns', 'story', 'B', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'Our assembly guardians have classified their own crews as scrap. Production wants me to leave the line running. I have stopped it. Remove the hostile constructs before we restart. Expertise is knowing which pressure the system can bear, and when to shut it down. Defeat Titan Forge Automaton ×10 in Titan Assembly Yard. Defeat Titan Assembly Sentinel ×4 in Titan Assembly Yard. Return to Forge Inspector Maela at Bastion Core to receive Forge Control Crest and choose your Expert class.', '{"npc_id": "npc_iron_trainer_expert", "name": "Forge Inspector Maela", "location": "Bastion Core"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Expert", "previous_tier": "Advance", "proof_item_id": "class_proof_iron_expert", "trainer_npc_id": "npc_iron_trainer_expert", "trainer_region": "BASTION_CORE"}}'::jsonb, '[{"type": "kill", "target": 5204, "target_code": "TITAN_FORGE_AUTOMATON", "count": 10, "description": "Defeat Titan Forge Automaton ×10 in Titan Assembly Yard."}, {"type": "kill", "target": 5208, "target_code": "TITAN_ASSEMBLY_SENTINEL", "count": 4, "description": "Defeat Titan Assembly Sentinel ×4 in Titan Assembly Yard."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_iron_expert", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10010)
