insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_iron_master', 'Command at Breaking Pressure', 'story', 'A', 'IRON_HEGEMONY', 'TITAN_ASSEMBLY_YARD', 'The proto cores are rebuilding the defense lattice faster than we can isolate it. Cut down the sentinel screen and the cores. Then report to me personally. This command plate is not permission to spend lives carelessly. It is the obligation to bring the line through. Defeat Titan Assembly Sentinel ×16 in Titan Assembly Yard. Defeat Titan Proto Core ×6 in Titan Assembly Yard. Return to General Torren at Bastion Core to receive Bastion Command Plate and choose your Master class.', '{"npc_id": "npc_iron_trainer_master", "name": "General Torren", "location": "Bastion Core"}'::jsonb, '{"min_level": 60, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Master", "previous_tier": "Expert", "proof_item_id": "class_proof_iron_master", "trainer_npc_id": "npc_iron_trainer_master", "trainer_region": "BASTION_CORE"}}'::jsonb, '[{"type": "kill", "target": 5208, "target_code": "TITAN_ASSEMBLY_SENTINEL", "count": 16, "description": "Defeat Titan Assembly Sentinel ×16 in Titan Assembly Yard."}, {"type": "kill", "target": 5209, "target_code": "TITAN_PROTO_CORE", "count": 6, "description": "Defeat Titan Proto Core ×6 in Titan Assembly Yard."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_iron_master", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10011)
