insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_meridian_base', 'A Favor with a Name', 'story', 'D', 'MERIDIAN_CARTEL', 'CORAL_WETLANDS', 'You found my door. That saves us one test. Wetland crawlers have pinned a ferry crew on the wrong bank, and one of them owes me a very interesting story. Clear the passage. Come back to Port and we will discuss what you are good at. The favor will have your name on it. Defeat Swamp Crawler ×5 in Coral Wetlands. Return to Captain Vex at Port Meridian to receive Vex''s Signed Passage and choose your Base class.', '{"npc_id": "npc_meridian_class_trainer", "name": "Captain Vex", "location": "Port Meridian"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Base", "previous_tier": null, "proof_item_id": "class_proof_meridian_base", "trainer_npc_id": "npc_meridian_class_trainer", "trainer_region": "PORT_MERIDIAN"}}'::jsonb, '[{"type": "kill", "target": 50013, "target_code": "SWAMP_CRAWLER", "count": 5, "description": "Defeat Swamp Crawler ×5 in Coral Wetlands."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_meridian_base", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10012)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_meridian_advance', 'The Route Nobody Owns', 'story', 'C', 'MERIDIAN_CARTEL', 'SMUGGLER_JUNGLE', 'Everyone claims the jungle route when it is safe. Nobody claims the people stranded on it now. Remove the stalkers and contraband constructs. Keep our carriers moving, and I will give you the cipher to a network that remembers who helped it. Defeat Jungle Stalker ×8 in Smuggler Jungle. Defeat Contraband Golem ×2 in Smuggler Jungle. Return to Route Broker Lysa at Port Meridian to receive Unlisted Route Cipher and choose your Advance class.', '{"npc_id": "npc_meridian_trainer_advance", "name": "Route Broker Lysa", "location": "Port Meridian"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Advance", "previous_tier": "Base", "proof_item_id": "class_proof_meridian_advance", "trainer_npc_id": "npc_meridian_trainer_advance", "trainer_region": "PORT_MERIDIAN"}}'::jsonb, '[{"type": "kill", "target": 5110, "target_code": "JUNGLE_STALKER", "count": 8, "description": "Defeat Jungle Stalker ×8 in Smuggler Jungle."}, {"type": "kill", "target": 5112, "target_code": "CONTRABAND_GOLEM", "count": 2, "description": "Defeat Contraband Golem ×2 in Smuggler Jungle."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_meridian_advance", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10013)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_meridian_expert', 'Insurance Below the Waterline', 'story', 'B', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'The divers'' insurers would rather pay a death benefit than clear the submerged approach. I would rather have living divers. Break the guardians and behemoths blocking the ruins. Bring the report to Port. A guarantee should protect a person, not merely settle a ledger. Defeat Cradle Sentinel ×10 in Sunken Aethel Ruin. Defeat Aethel Behemoth ×4 in Sunken Aethel Ruin. Return to Diver Marshal Corin at Port Meridian to receive Deepwater Guarantee Seal and choose your Expert class.', '{"npc_id": "npc_meridian_trainer_expert", "name": "Diver Marshal Corin", "location": "Port Meridian"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Expert", "previous_tier": "Advance", "proof_item_id": "class_proof_meridian_expert", "trainer_npc_id": "npc_meridian_trainer_expert", "trainer_region": "PORT_MERIDIAN"}}'::jsonb, '[{"type": "kill", "target": 5201, "target_code": "CRADLE_SENTINEL", "count": 10, "description": "Defeat Cradle Sentinel ×10 in Sunken Aethel Ruin."}, {"type": "kill", "target": 5200, "target_code": "AETHEL_BEHEMOTH", "count": 4, "description": "Defeat Aethel Behemoth ×4 in Sunken Aethel Ruin."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_meridian_expert", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10014)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_meridian_master', 'The Debt We Choose to Keep', 'story', 'A', 'MERIDIAN_CARTEL', 'SUNKEN_AETHEL_RUIN', 'Our oldest contract allows us to walk away from the flooded route. We are staying. Push back the behemoths and leviathans so the last crews can surface. When I hand you the covenant coin, understand this: some debts are worth choosing, even when nobody can collect. Defeat Aethel Behemoth ×16 in Sunken Aethel Ruin. Defeat Sunken Aethel Leviathan ×6 in Sunken Aethel Ruin. Return to Keeper of Debts Sable at Port Meridian to receive Meridian Covenant Coin and choose your Master class.', '{"npc_id": "npc_meridian_trainer_master", "name": "Keeper of Debts Sable", "location": "Port Meridian"}'::jsonb, '{"min_level": 60, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Master", "previous_tier": "Expert", "proof_item_id": "class_proof_meridian_master", "trainer_npc_id": "npc_meridian_trainer_master", "trainer_region": "PORT_MERIDIAN"}}'::jsonb, '[{"type": "kill", "target": 5200, "target_code": "AETHEL_BEHEMOTH", "count": 16, "description": "Defeat Aethel Behemoth ×16 in Sunken Aethel Ruin."}, {"type": "kill", "target": 5205, "target_code": "SUNKEN_AETHEL_LEVIATHAN", "count": 6, "description": "Defeat Sunken Aethel Leviathan ×6 in Sunken Aethel Ruin."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_meridian_master", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10015)
