insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_omnicorp_base', 'A Performance Worth Signing', 'story', 'D', 'OMNICORP', 'HIGHLAND_PLATEAU', 'Your projection is promising. I do not certify projections. Rogue plateau drones are damaging a crew''s survey equipment. Neutralize them and return to my office. The competency wafer requires a verifiable result. Once you have it, choose the discipline in which you intend to outperform your own baseline. Defeat Plateau Drone ×5 in Highland Plateau. Return to Director Astra Vey at The Spire to receive Astra''s Competency Wafer and choose your Base class.', '{"npc_id": "npc_omnicorp_class_trainer", "name": "Director Astra Vey", "location": "The Spire"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Base", "previous_tier": null, "proof_item_id": "class_proof_omnicorp_base", "trainer_npc_id": "npc_omnicorp_class_trainer", "trainer_region": "THE_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 5014, "target_code": "PLATEAU_DRONE", "count": 5, "description": "Defeat Plateau Drone ×5 in Highland Plateau."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_omnicorp_base", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10016)
