insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_omnicorp_advance', 'The Human Cost of Downtime', 'story', 'C', 'OMNICORP', 'EXTRACTION_ZONE_DELTA', 'Delta calls this an output problem. My maintenance crew calls it a survival problem. Remove the mining drones and their assault escort. I will sign your recovery license when the site is usable again. Efficient work gets people through their shift alive. Defeat Delta Mining Drone ×8 in Extraction Zone Delta. Defeat Delta Assault Drone ×2 in Extraction Zone Delta. Return to Operations Lead Tessa Lin at The Spire to receive Delta Recovery License and choose your Advance class.', '{"npc_id": "npc_omnicorp_trainer_advance", "name": "Operations Lead Tessa Lin", "location": "The Spire"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Advance", "previous_tier": "Base", "proof_item_id": "class_proof_omnicorp_advance", "trainer_npc_id": "npc_omnicorp_trainer_advance", "trainer_region": "THE_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 5160, "target_code": "DELTA_MINING_DRONE", "count": 8, "description": "Defeat Delta Mining Drone ×8 in Extraction Zone Delta."}, {"type": "kill", "target": 5162, "target_code": "DELTA_ASSAULT_DRONE", "count": 2, "description": "Defeat Delta Assault Drone ×2 in Extraction Zone Delta."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_omnicorp_advance", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10017)
