insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_omnicorp_expert', 'Authority to Halt the Reactor', 'story', 'B', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'You are being evaluated for override authority. The reactor''s defense units are obstructing emergency access. Clear them. Do not confuse a green dashboard with a safe facility. An expert must be willing to stop a profitable process when its evidence no longer supports operation. Defeat Titan Assembly Drone ×10 in Skybridge Reactor. Defeat Titan Assembly Sentinel ×4 in Skybridge Reactor. Return to Chief Auditor Ren at The Spire to receive Reactor Override Key and choose your Expert class.', '{"npc_id": "npc_omnicorp_trainer_expert", "name": "Chief Auditor Ren", "location": "The Spire"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Expert", "previous_tier": "Advance", "proof_item_id": "class_proof_omnicorp_expert", "trainer_npc_id": "npc_omnicorp_trainer_expert", "trainer_region": "THE_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 5207, "target_code": "TITAN_ASSEMBLY_DRONE", "count": 10, "description": "Defeat Titan Assembly Drone ×10 in Skybridge Reactor."}, {"type": "kill", "target": 5208, "target_code": "TITAN_ASSEMBLY_SENTINEL", "count": 4, "description": "Defeat Titan Assembly Sentinel ×4 in Skybridge Reactor."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_omnicorp_expert", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10018)
