insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_omnicorp_master', 'The Liability We Will Not Export', 'story', 'A', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'The board suggests exporting the failing cores. That would export the casualties as well. Contain the sentinel units and proto cores here, on our own ground. Return with the record. This mandate will give you authority, and a liability you may never hide in somebody else''s account. Defeat Titan Assembly Sentinel ×16 in Skybridge Reactor. Defeat Titan Proto Core ×6 in Skybridge Reactor. Return to Executive Director Iona Hale at The Spire to receive OmniCorp Executive Mandate and choose your Master class.', '{"npc_id": "npc_omnicorp_trainer_master", "name": "Executive Director Iona Hale", "location": "The Spire"}'::jsonb, '{"min_level": 60, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Master", "previous_tier": "Expert", "proof_item_id": "class_proof_omnicorp_master", "trainer_npc_id": "npc_omnicorp_trainer_master", "trainer_region": "THE_SPIRE"}}'::jsonb, '[{"type": "kill", "target": 5208, "target_code": "TITAN_ASSEMBLY_SENTINEL", "count": 16, "description": "Defeat Titan Assembly Sentinel ×16 in Skybridge Reactor."}, {"type": "kill", "target": 5209, "target_code": "TITAN_PROTO_CORE", "count": 6, "description": "Defeat Titan Proto Core ×6 in Skybridge Reactor."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_omnicorp_master", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10019)
