insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_shard_base', 'Listen Before You Wield', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'GLOWVINE_FOREST', 'Power does not make the forest yours. Listen first. The barklings have turned on the paths used by our seed keepers. Still their violence and return to the Sanctum. I will entrust you with a listening shard. The calling you choose must leave room for voices other than your own. Defeat Forest Barkling ×5 in Glowvine Forest. Return to Oracle Seraphel at Sanctum to receive Listening Shard and choose your Base class.', '{"npc_id": "npc_shard_class_trainer", "name": "Oracle Seraphel", "location": "Sanctum"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Base", "previous_tier": null, "proof_item_id": "class_proof_shard_base", "trainer_npc_id": "npc_shard_class_trainer", "trainer_region": "SANCTUM"}}'::jsonb, '[{"type": "kill", "target": 5018, "target_code": "FOREST_BARKLING", "count": 5, "description": "Defeat Forest Barkling ×5 in Glowvine Forest."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_shard_base", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10020)
