insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_shard_advance', 'The Root Remembers', 'story', 'C', 'CHILDREN_OF_THE_SHARD', 'SHARDROOT_SWAMP', 'The swamp remembers every wound, but memory alone cannot shelter a traveler. Creepers and titans now hold the root paths. Open them for the caretakers. Bring your account back to me; I will help you hear what survival has changed in you. Defeat Shardroot Creeper ×8 in Shardroot Swamp. Defeat Shardroot Titan ×2 in Shardroot Swamp. Return to Root Listener Amara at Sanctum to receive Rootmemory Votive and choose your Advance class.', '{"npc_id": "npc_shard_trainer_advance", "name": "Root Listener Amara", "location": "Sanctum"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Advance", "previous_tier": "Base", "proof_item_id": "class_proof_shard_advance", "trainer_npc_id": "npc_shard_trainer_advance", "trainer_region": "SANCTUM"}}'::jsonb, '[{"type": "kill", "target": 5120, "target_code": "SHARDROOT_CREEPER", "count": 8, "description": "Defeat Shardroot Creeper ×8 in Shardroot Swamp."}, {"type": "kill", "target": 5122, "target_code": "SHARDROOT_TITAN", "count": 2, "description": "Defeat Shardroot Titan ×2 in Shardroot Swamp."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_shard_advance", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10021)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_shard_expert', 'The Wound Beneath the Altar', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'HEARTWOOD_ALTAR', 'The altar''s defenders strike at the people trying to mend it. Some call that a holy judgment. I call it another wound. End the hostile guardians'' hold over the approach. Return to Sanctum. I need a witness who sees suffering clearly, even when it contradicts a comforting story. Defeat Titan Forge Automaton ×10 in Heartwood Altar. Defeat Aethel Behemoth ×4 in Heartwood Altar. Return to Woundkeeper Oriel at Sanctum to receive Heartwood Witness Stone and choose your Expert class.', '{"npc_id": "npc_shard_trainer_expert", "name": "Woundkeeper Oriel", "location": "Sanctum"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Expert", "previous_tier": "Advance", "proof_item_id": "class_proof_shard_expert", "trainer_npc_id": "npc_shard_trainer_expert", "trainer_region": "SANCTUM"}}'::jsonb, '[{"type": "kill", "target": 5204, "target_code": "TITAN_FORGE_AUTOMATON", "count": 10, "description": "Defeat Titan Forge Automaton ×10 in Heartwood Altar."}, {"type": "kill", "target": 5200, "target_code": "AETHEL_BEHEMOTH", "count": 4, "description": "Defeat Aethel Behemoth ×4 in Heartwood Altar."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_shard_expert", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10022)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_shard_master', 'A Vow for Those Who Follow', 'story', 'A', 'CHILDREN_OF_THE_SHARD', 'HEARTWOOD_ALTAR', 'We will leave this altar to children who did not make its scars. Push back the beasts keeping our keepers outside. Do not offer me a claim of divine favor. Offer them a place they can enter safely. That is the vow this reliquary will hold. Defeat Aethel Behemoth ×16 in Heartwood Altar. Defeat Sunken Aethel Leviathan ×6 in Heartwood Altar. Return to Elder Naeva at Sanctum to receive Sanctum Keeper Reliquary and choose your Master class.', '{"npc_id": "npc_shard_trainer_master", "name": "Elder Naeva", "location": "Sanctum"}'::jsonb, '{"min_level": 60, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Master", "previous_tier": "Expert", "proof_item_id": "class_proof_shard_master", "trainer_npc_id": "npc_shard_trainer_master", "trainer_region": "SANCTUM"}}'::jsonb, '[{"type": "kill", "target": 5200, "target_code": "AETHEL_BEHEMOTH", "count": 16, "description": "Defeat Aethel Behemoth ×16 in Heartwood Altar."}, {"type": "kill", "target": 5205, "target_code": "SUNKEN_AETHEL_LEVIATHAN", "count": 6, "description": "Defeat Sunken Aethel Leviathan ×6 in Heartwood Altar."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_shard_master", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10023)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_legion_base', 'A Place in the Formation', 'story', 'D', 'STARFORGED_LEGION', 'DUNE_OUTSKIRTS', 'Stand here, where I can see your footing. The dune scavengers are threatening our water runners. Clear the outskirts, then return to the fortress. I train people for a place in the formation, not a lonely death in the sand. Earn your knot, and we will choose how you serve beside us. Defeat Dune Scavenger ×5 in Dune Outskirts. Return to Centurion Valka at Fortress Kaelen to receive Valka''s Formation Knot and choose your Base class.', '{"npc_id": "npc_legion_class_trainer", "name": "Centurion Valka", "location": "Fortress Kaelen"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Base", "previous_tier": null, "proof_item_id": "class_proof_legion_base", "trainer_npc_id": "npc_legion_class_trainer", "trainer_region": "FORTRESS_KAELEN"}}'::jsonb, '[{"type": "kill", "target": 50019, "target_code": "DUNE_SCAVENGER", "count": 5, "description": "Defeat Dune Scavenger ×5 in Dune Outskirts."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_legion_base", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10024)
on conflict (id) do update set "title"=excluded."title", "type"=excluded."type", "rank"=excluded."rank", "faction"=excluded."faction", "region"=excluded."region", "description"=excluded."description", "quest_giver"=excluded."quest_giver", "requirements"=excluded."requirements", "objectives"=excluded."objectives", "rewards"=excluded."rewards", "repeatable"=excluded."repeatable", "daily"=excluded."daily", "quest_chain_next"=excluded."quest_chain_next", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_legion_advance', 'The Standard Does Not Walk Alone', 'story', 'C', 'STARFORGED_LEGION', 'SCORCHED_BADLANDS', 'The standard is useless if nobody makes it through the badlands beneath it. Ash hounds and brutes are harrying our march. Clear them and report to the fortress. I will judge your advance by the ground the next formation can safely cross. Defeat Ash Hound ×8 in Scorched Badlands. Defeat Badland Brute ×2 in Scorched Badlands. Return to Marchwarden Sera at Fortress Kaelen to receive Marchwarden Standard Tab and choose your Advance class.', '{"npc_id": "npc_legion_trainer_advance", "name": "Marchwarden Sera", "location": "Fortress Kaelen"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Advance", "previous_tier": "Base", "proof_item_id": "class_proof_legion_advance", "trainer_npc_id": "npc_legion_trainer_advance", "trainer_region": "FORTRESS_KAELEN"}}'::jsonb, '[{"type": "kill", "target": 5130, "target_code": "ASH_HOUND", "count": 8, "description": "Defeat Ash Hound ×8 in Scorched Badlands."}, {"type": "kill", "target": 5131, "target_code": "BADLAND_BRUTE", "count": 2, "description": "Defeat Badland Brute ×2 in Scorched Badlands."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_legion_advance", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10025)
