insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_legion_expert', 'Names Before Numbers', 'story', 'B', 'STARFORGED_LEGION', 'FORGE_CANYON_DEPTHS', 'Every empty place in formation has a name. The canyon''s machines are making more of them. Clear the drone ranks and their sentinels. Bring the record back. An expert sees a missing fighter before they see a convenient gap in the roster. Defeat Titan Assembly Drone ×10 in Forge Canyon Depths. Defeat Titan Assembly Sentinel ×4 in Forge Canyon Depths. Return to Rollkeeper Bren at Fortress Kaelen to receive Rollkeeper Steel Token and choose your Expert class.', '{"npc_id": "npc_legion_trainer_expert", "name": "Rollkeeper Bren", "location": "Fortress Kaelen"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Expert", "previous_tier": "Advance", "proof_item_id": "class_proof_legion_expert", "trainer_npc_id": "npc_legion_trainer_expert", "trainer_region": "FORTRESS_KAELEN"}}'::jsonb, '[{"type": "kill", "target": 5207, "target_code": "TITAN_ASSEMBLY_DRONE", "count": 10, "description": "Defeat Titan Assembly Drone ×10 in Forge Canyon Depths."}, {"type": "kill", "target": 5208, "target_code": "TITAN_ASSEMBLY_SENTINEL", "count": 4, "description": "Defeat Titan Assembly Sentinel ×4 in Forge Canyon Depths."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_legion_expert", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10026)
