insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "quest_chain_next", "source_file", "sort_order") values ('class_trial_legion_master', 'A Home Beyond the March', 'story', 'A', 'STARFORGED_LEGION', 'FORGE_CANYON_DEPTHS', 'Our elders promised a home beyond the march. It cannot be a fortress that devours its builders. Break the sentinels and proto cores controlling the canyon approach. Return to Kaelen. Carry this hearth standard as a duty to the living, as well as to the names we remember. Defeat Titan Assembly Sentinel ×16 in Forge Canyon Depths. Defeat Titan Proto Core ×6 in Forge Canyon Depths. Return to Legate Ashra at Fortress Kaelen to receive Starforged Hearth Standard and choose your Master class.', '{"npc_id": "npc_legion_trainer_master", "name": "Legate Ashra", "location": "Fortress Kaelen"}'::jsonb, '{"min_level": 60, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "class_promotion": {"tier": "Master", "previous_tier": "Expert", "proof_item_id": "class_proof_legion_master", "trainer_npc_id": "npc_legion_trainer_master", "trainer_region": "FORTRESS_KAELEN"}}'::jsonb, '[{"type": "kill", "target": 5208, "target_code": "TITAN_ASSEMBLY_SENTINEL", "count": 16, "description": "Defeat Titan Assembly Sentinel ×16 in Forge Canyon Depths."}, {"type": "kill", "target": 5209, "target_code": "TITAN_PROTO_CORE", "count": 6, "description": "Defeat Titan Proto Core ×6 in Forge Canyon Depths."}]'::jsonb, '{"exp": 0, "currency": 0, "crd": 0, "reputation": 0, "items": [{"item_id": "class_proof_legion_master", "quantity": 1}]}'::jsonb, false, false, null, 'quest_list.json', 10027)
