insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "auto_accept", "quest_chain_next", "source_file", "sort_order") values ('msq_tutorial_01', 'First Contact', 'story', 'D', 'NONE', '', 'Open EXPLORE and win your first battle.', '{"npc_id": "npc_class_advisor", "name": "Guide Axiom", "location": "Nexus Core"}'::jsonb, '{"min_level": 1, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "action", "target": "win_battle", "count": 1, "description": "Open EXPLORE and win your first battle."}]'::jsonb, '{"exp": 120, "currency": 50, "crd": 50, "reputation": 0, "items": []}'::jsonb, false, false, true, 'msq_tutorial_02', 'quest_list.json', 10028)
