insert into public.quests ("id", "title", "type", "rank", "faction", "region", "description", "quest_giver", "requirements", "objectives", "rewards", "repeatable", "daily", "auto_accept", "quest_chain_next", "source_file", "sort_order") values ('msq_tutorial_02', 'Growing Stronger', 'story', 'D', 'NONE', '', 'Reach Level 2 — then spend your stat point in Profile.', '{"npc_id": "npc_class_advisor", "name": "Guide Axiom", "location": "Nexus Core"}'::jsonb, '{"min_level": 1, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "action", "target": "reach_level_2", "count": 1, "description": "Reach Level 2 — then spend your stat point in Profile."}]'::jsonb, '{"exp": 150, "currency": 50, "crd": 50, "reputation": 0, "items": []}'::jsonb, false, false, true, 'msq_tutorial_04', 'quest_list.json', 10029)
