insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_concordium_base', 'class_trial_concordium_base', 'npc_concordium_class_trainer', 'offer', '[{"id": "offer", "text": "Five levels of field work. Good. Now make it count for someone else. Feral roots have closed the garden path our ration crews use. I will not ask for trophies; I want that route safe. Keep your breathing steady, finish the drill, and return to me. Then we choose the role you can actually sustain.\n\nDefeat Feral Rootling ×5 in Aethel Gardens. Then return here for Civic Oath Seal.", "options": [{"text": "I will keep that path safe.", "next": "exit", "action": "accept_class_trial:class_trial_concordium_base"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Five levels of field work.\n\nDefeat Feral Rootling ×5 in Aethel Gardens.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The ration crews are moving again. You held the line without forgetting who stood behind it. I can now issue Civic Oath Seal. Choose your Base discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_concordium_base"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The ration crews are moving again. You held the line without forgetting who stood behind it. Your Civic Oath Seal is ready. We can choose your Base discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10000)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_concordium_advance', 'class_trial_concordium_advance', 'npc_concordium_trainer_advance', 'offer', '[{"id": "offer", "text": "Kael taught you to hold a line. I need you to move one. The outer-ring wardens are driving supply crews back into the broken quarter. Clear a passage without treating every ruin as expendable. A specialist earns trust when the next crew can follow them home.\n\nDefeat Cradle Fragment Beast ×8 in Cradle Outer Ring. Defeat Cradle Warden ×2 in Cradle Outer Ring. Then return here for Routekeeper Warrant.", "options": [{"text": "I will keep that path safe.", "next": "exit", "action": "accept_class_trial:class_trial_concordium_advance"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Kael taught you to hold a line.\n\nDefeat Cradle Fragment Beast ×8 in Cradle Outer Ring. Defeat Cradle Warden ×2 in Cradle Outer Ring.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The route is open. I can assign crews to it, rather than merely drawing it on a map. I can now issue Routekeeper Warrant. Choose your Advance discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_concordium_advance"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The route is open. I can assign crews to it, rather than merely drawing it on a map. Your Routekeeper Warrant is ready. We can choose your Advance discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10001)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_concordium_expert', 'class_trial_concordium_expert', 'npc_concordium_trainer_expert', 'offer', '[{"id": "offer", "text": "The stabilization protocol assumes obedient sentinels. Our sentinels have stopped obeying. I need evidence that you can respond when the procedure fails: remove the hostile units inside the exclusion zone. Report what the ledger records, not what you wish happened.\n\nDefeat Cradle Sentinel ×10 in Inner Cradle Exclusion. Defeat Cradle Purifier ×4 in Inner Cradle Exclusion. Then return here for Cradle Stabilization Charter.", "options": [{"text": "I will keep that path safe.", "next": "exit", "action": "accept_class_trial:class_trial_concordium_expert"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The stabilization protocol assumes obedient sentinels.\n\nDefeat Cradle Sentinel ×10 in Inner Cradle Exclusion. Defeat Cradle Purifier ×4 in Inner Cradle Exclusion.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "Your report is sound. The protocol can now be rewritten around what actually happened. I can now issue Cradle Stabilization Charter. Choose your Expert discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_concordium_expert"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "Your report is sound. The protocol can now be rewritten around what actually happened. Your Cradle Stabilization Charter is ready. We can choose your Expert discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10002)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_concordium_master', 'class_trial_concordium_master', 'npc_concordium_trainer_master', 'offer', '[{"id": "offer", "text": "There is one convoy left inside the exclusion zone. Command calls the route unrecoverable. I have their names here. Break the beasts controlling that corridor and bring your report to me. Mastery means accepting responsibility when the easy order is to abandon people.\n\nDefeat Arcane Rift Beast ×16 in Inner Cradle Exclusion. Defeat Cradle Void Titanling ×6 in Inner Cradle Exclusion. Then return here for Concordium Steward Sigil.", "options": [{"text": "I will keep that path safe.", "next": "exit", "action": "accept_class_trial:class_trial_concordium_master"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "There is one convoy left inside the exclusion zone.\n\nDefeat Arcane Rift Beast ×16 in Inner Cradle Exclusion. Defeat Cradle Void Titanling ×6 in Inner Cradle Exclusion.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "Every name on my list has a route out. This sigil carries their trust, not just my signature. I can now issue Concordium Steward Sigil. Choose your Master discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_concordium_master"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "Every name on my list has a route out. This sigil carries their trust, not just my signature. Your Concordium Steward Sigil is ready. We can choose your Master discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10003)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_arcanum_base', 'class_trial_arcanum_base', 'npc_arcanum_class_trainer', 'offer', '[{"id": "offer", "text": "A class is a hypothesis about what you might become. Do not mistake it for proof. Wild Mushrooms are interrupting our slope readings; confront them and let the ledger record the results. Return with observations. I can teach a promising mind. I cannot teach a mind that invents its evidence.\n\nDefeat Wild Mushroom ×5 in Crystal Slope. Then return here for Resonance Thesis Prism.", "options": [{"text": "I will bring back evidence.", "next": "exit", "action": "accept_class_trial:class_trial_arcanum_base"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "A class is a hypothesis about what you might become.\n\nDefeat Wild Mushroom ×5 in Crystal Slope.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "An honest record, including uncertainty. That is a better beginning than a spectacular claim. I can now issue Resonance Thesis Prism. Choose your Base discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_arcanum_base"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "An honest record, including uncertainty. That is a better beginning than a spectacular claim. Your Resonance Thesis Prism is ready. We can choose your Base discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10004)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_arcanum_advance', 'class_trial_arcanum_advance', 'npc_arcanum_trainer_advance', 'offer', '[{"id": "offer", "text": "The cavern echoes have begun answering signals nobody transmitted. My last team withdrew, correctly. Establish a safe baseline against the bats and the resonant echoes before I send anyone back. Curiosity should widen our understanding, not empty our chairs.\n\nDefeat Resonance Bat ×8 in Resonance Caverns. Defeat Resonance Echo ×2 in Resonance Caverns. Then return here for Echo Calibration Lens.", "options": [{"text": "I will bring back evidence.", "next": "exit", "action": "accept_class_trial:class_trial_arcanum_advance"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The cavern echoes have begun answering signals nobody transmitted.\n\nDefeat Resonance Bat ×8 in Resonance Caverns. Defeat Resonance Echo ×2 in Resonance Caverns.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The baseline holds. We can enter those caverns with a reasoned plan rather than a wish. I can now issue Echo Calibration Lens. Choose your Advance discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_arcanum_advance"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The baseline holds. We can enter those caverns with a reasoned plan rather than a wish. Your Echo Calibration Lens is ready. We can choose your Advance discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10005)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_arcanum_expert', 'class_trial_arcanum_expert', 'npc_arcanum_trainer_expert', 'offer', '[{"id": "offer", "text": "The peak guardians respond differently to each pulse. Your task is not to declare them understood; it is to stop the hostile pattern long enough for our instruments to survive. Bring a complete field record. I will challenge every conclusion you cannot support.\n\nDefeat Shard Pulse Sentinel ×10 in Shard Pulse Peak. Defeat Shard Pulse Guardian ×4 in Shard Pulse Peak. Then return here for Peer Witness Crystal.", "options": [{"text": "I will bring back evidence.", "next": "exit", "action": "accept_class_trial:class_trial_arcanum_expert"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The peak guardians respond differently to each pulse.\n\nDefeat Shard Pulse Sentinel ×10 in Shard Pulse Peak. Defeat Shard Pulse Guardian ×4 in Shard Pulse Peak.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "Your evidence survives scrutiny. The witness crystal certifies the work, not infallibility. I can now issue Peer Witness Crystal. Choose your Expert discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_arcanum_expert"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "Your evidence survives scrutiny. The witness crystal certifies the work, not infallibility. Your Peer Witness Crystal is ready. We can choose your Expert discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10006)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_arcanum_master', 'class_trial_arcanum_master', 'npc_arcanum_trainer_master', 'offer', '[{"id": "offer", "text": "We could publish a triumph by sacrificing the next expedition. I refuse. Contain the peak''s guardians and tyrants so that discovery can continue without another missing team. A master leaves knowledge others can test, and a path by which they can return.\n\nDefeat Shard Pulse Guardian ×16 in Shard Pulse Peak. Defeat Shard Pulse Tyrant ×6 in Shard Pulse Peak. Then return here for Arcanum Living Codex.", "options": [{"text": "I will bring back evidence.", "next": "exit", "action": "accept_class_trial:class_trial_arcanum_master"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "We could publish a triumph by sacrificing the next expedition.\n\nDefeat Shard Pulse Guardian ×16 in Shard Pulse Peak. Defeat Shard Pulse Tyrant ×6 in Shard Pulse Peak.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The expedition has returned. This codex remains open: your mastery includes admitting what we still do not know. I can now issue Arcanum Living Codex. Choose your Master discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_arcanum_master"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The expedition has returned. This codex remains open: your mastery includes admitting what we still do not know. Your Arcanum Living Codex is ready. We can choose your Master discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10007)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_iron_base', 'class_trial_iron_base', 'npc_hegemony_class_trainer', 'offer', '[{"id": "offer", "text": "You have survived long enough to train properly. Scrap drones are tearing up the recovery lanes. Shut them down. No borrowed commendation, no purchased rank. Finish the work, return to Bastion, and I will put a tempered rivet in your hand. What you do next is your choice.\n\nDefeat Scrap Drone ×5 in Scrap Field. Then return here for Tempered Service Rivet.", "options": [{"text": "I will complete the work.", "next": "exit", "action": "accept_class_trial:class_trial_iron_base"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "You have survived long enough to train properly.\n\nDefeat Scrap Drone ×5 in Scrap Field.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The recovery lanes are usable. Good. That rivet was tempered in work, not ceremony. I can now issue Tempered Service Rivet. Choose your Base discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_iron_base"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The recovery lanes are usable. Good. That rivet was tempered in work, not ceremony. Your Tempered Service Rivet is ready. We can choose your Base discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10008)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_iron_advance', 'class_trial_iron_advance', 'npc_iron_trainer_advance', 'offer', '[{"id": "offer", "text": "A brilliant fighter with an empty supply wagon is an expensive corpse. The graveyard machines are stopping our salvage crews. Clear the wreckers and their sentinel escorts. I want usable lanes at shift change, not a speech about your courage.\n\nDefeat War Machine Wrecker ×8 in War Machine Graveyard. Defeat War Machine Sentinel ×2 in War Machine Graveyard. Then return here for Supplyline Iron Writ.", "options": [{"text": "I will complete the work.", "next": "exit", "action": "accept_class_trial:class_trial_iron_advance"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "A brilliant fighter with an empty supply wagon is an expensive corpse.\n\nDefeat War Machine Wrecker ×8 in War Machine Graveyard. Defeat War Machine Sentinel ×2 in War Machine Graveyard.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "Supplies are moving. The crews will notice your result before they ever learn your rank. I can now issue Supplyline Iron Writ. Choose your Advance discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_iron_advance"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "Supplies are moving. The crews will notice your result before they ever learn your rank. Your Supplyline Iron Writ is ready. We can choose your Advance discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10009)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_iron_expert', 'class_trial_iron_expert', 'npc_iron_trainer_expert', 'offer', '[{"id": "offer", "text": "Our assembly guardians have classified their own crews as scrap. Production wants me to leave the line running. I have stopped it. Remove the hostile constructs before we restart. Expertise is knowing which pressure the system can bear, and when to shut it down.\n\nDefeat Titan Forge Automaton ×10 in Titan Assembly Yard. Defeat Titan Assembly Sentinel ×4 in Titan Assembly Yard. Then return here for Forge Control Crest.", "options": [{"text": "I will complete the work.", "next": "exit", "action": "accept_class_trial:class_trial_iron_expert"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Our assembly guardians have classified their own crews as scrap.\n\nDefeat Titan Forge Automaton ×10 in Titan Assembly Yard. Defeat Titan Assembly Sentinel ×4 in Titan Assembly Yard.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The shutdown held. You chose the crews over a pleasing output figure. I can now issue Forge Control Crest. Choose your Expert discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_iron_expert"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The shutdown held. You chose the crews over a pleasing output figure. Your Forge Control Crest is ready. We can choose your Expert discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10010)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_iron_master', 'class_trial_iron_master', 'npc_iron_trainer_master', 'offer', '[{"id": "offer", "text": "The proto cores are rebuilding the defense lattice faster than we can isolate it. Cut down the sentinel screen and the cores. Then report to me personally. This command plate is not permission to spend lives carelessly. It is the obligation to bring the line through.\n\nDefeat Titan Assembly Sentinel ×16 in Titan Assembly Yard. Defeat Titan Proto Core ×6 in Titan Assembly Yard. Then return here for Bastion Command Plate.", "options": [{"text": "I will complete the work.", "next": "exit", "action": "accept_class_trial:class_trial_iron_master"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The proto cores are rebuilding the defense lattice faster than we can isolate it.\n\nDefeat Titan Assembly Sentinel ×16 in Titan Assembly Yard. Defeat Titan Proto Core ×6 in Titan Assembly Yard.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The lattice is under our control. Take the plate, and remember exactly what command costs. I can now issue Bastion Command Plate. Choose your Master discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_iron_master"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The lattice is under our control. Take the plate, and remember exactly what command costs. Your Bastion Command Plate is ready. We can choose your Master discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10011)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_meridian_base', 'class_trial_meridian_base', 'npc_meridian_class_trainer', 'offer', '[{"id": "offer", "text": "You found my door. That saves us one test. Wetland crawlers have pinned a ferry crew on the wrong bank, and one of them owes me a very interesting story. Clear the passage. Come back to Port and we will discuss what you are good at. The favor will have your name on it.\n\nDefeat Swamp Crawler ×5 in Coral Wetlands. Then return here for Vex''s Signed Passage.", "options": [{"text": "Consider the favor accepted.", "next": "exit", "action": "accept_class_trial:class_trial_meridian_base"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "You found my door.\n\nDefeat Swamp Crawler ×5 in Coral Wetlands.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The ferry crew is safe. A useful favor, and a signature I will remember. I can now issue Vex''s Signed Passage. Choose your Base discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_meridian_base"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The ferry crew is safe. A useful favor, and a signature I will remember. Your Vex''s Signed Passage is ready. We can choose your Base discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10012)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_meridian_advance', 'class_trial_meridian_advance', 'npc_meridian_trainer_advance', 'offer', '[{"id": "offer", "text": "Everyone claims the jungle route when it is safe. Nobody claims the people stranded on it now. Remove the stalkers and contraband constructs. Keep our carriers moving, and I will give you the cipher to a network that remembers who helped it.\n\nDefeat Jungle Stalker ×8 in Smuggler Jungle. Defeat Contraband Golem ×2 in Smuggler Jungle. Then return here for Unlisted Route Cipher.", "options": [{"text": "Consider the favor accepted.", "next": "exit", "action": "accept_class_trial:class_trial_meridian_advance"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Everyone claims the jungle route when it is safe.\n\nDefeat Jungle Stalker ×8 in Smuggler Jungle. Defeat Contraband Golem ×2 in Smuggler Jungle.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The carriers are moving. Your cipher is earned; the network will answer your call. I can now issue Unlisted Route Cipher. Choose your Advance discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_meridian_advance"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The carriers are moving. Your cipher is earned; the network will answer your call. Your Unlisted Route Cipher is ready. We can choose your Advance discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10013)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_meridian_expert', 'class_trial_meridian_expert', 'npc_meridian_trainer_expert', 'offer', '[{"id": "offer", "text": "The divers'' insurers would rather pay a death benefit than clear the submerged approach. I would rather have living divers. Break the guardians and behemoths blocking the ruins. Bring the report to Port. A guarantee should protect a person, not merely settle a ledger.\n\nDefeat Cradle Sentinel ×10 in Sunken Aethel Ruin. Defeat Aethel Behemoth ×4 in Sunken Aethel Ruin. Then return here for Deepwater Guarantee Seal.", "options": [{"text": "Consider the favor accepted.", "next": "exit", "action": "accept_class_trial:class_trial_meridian_expert"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The divers'' insurers would rather pay a death benefit than clear the submerged approach.\n\nDefeat Cradle Sentinel ×10 in Sunken Aethel Ruin. Defeat Aethel Behemoth ×4 in Sunken Aethel Ruin.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The divers came back breathing. That is a guarantee I am willing to sign. I can now issue Deepwater Guarantee Seal. Choose your Expert discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_meridian_expert"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The divers came back breathing. That is a guarantee I am willing to sign. Your Deepwater Guarantee Seal is ready. We can choose your Expert discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10014)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_meridian_master', 'class_trial_meridian_master', 'npc_meridian_trainer_master', 'offer', '[{"id": "offer", "text": "Our oldest contract allows us to walk away from the flooded route. We are staying. Push back the behemoths and leviathans so the last crews can surface. When I hand you the covenant coin, understand this: some debts are worth choosing, even when nobody can collect.\n\nDefeat Aethel Behemoth ×16 in Sunken Aethel Ruin. Defeat Sunken Aethel Leviathan ×6 in Sunken Aethel Ruin. Then return here for Meridian Covenant Coin.", "options": [{"text": "Consider the favor accepted.", "next": "exit", "action": "accept_class_trial:class_trial_meridian_master"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Our oldest contract allows us to walk away from the flooded route.\n\nDefeat Aethel Behemoth ×16 in Sunken Aethel Ruin. Defeat Sunken Aethel Leviathan ×6 in Sunken Aethel Ruin.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "No one was left below. Keep the coin. It is a promise with witnesses, not loose currency. I can now issue Meridian Covenant Coin. Choose your Master discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_meridian_master"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "No one was left below. Keep the coin. It is a promise with witnesses, not loose currency. Your Meridian Covenant Coin is ready. We can choose your Master discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10015)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_omnicorp_base', 'class_trial_omnicorp_base', 'npc_omnicorp_class_trainer', 'offer', '[{"id": "offer", "text": "Your projection is promising. I do not certify projections. Rogue plateau drones are damaging a crew''s survey equipment. Neutralize them and return to my office. The competency wafer requires a verifiable result. Once you have it, choose the discipline in which you intend to outperform your own baseline.\n\nDefeat Plateau Drone ×5 in Highland Plateau. Then return here for Astra''s Competency Wafer.", "options": [{"text": "I will deliver a verifiable result.", "next": "exit", "action": "accept_class_trial:class_trial_omnicorp_base"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Your projection is promising.\n\nDefeat Plateau Drone ×5 in Highland Plateau.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "Result verified. The wafer is signed. Your next discipline will be judged by what you do with it. I can now issue Astra''s Competency Wafer. Choose your Base discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_omnicorp_base"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "Result verified. The wafer is signed. Your next discipline will be judged by what you do with it. Your Astra''s Competency Wafer is ready. We can choose your Base discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10016)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_omnicorp_advance', 'class_trial_omnicorp_advance', 'npc_omnicorp_trainer_advance', 'offer', '[{"id": "offer", "text": "Delta calls this an output problem. My maintenance crew calls it a survival problem. Remove the mining drones and their assault escort. I will sign your recovery license when the site is usable again. Efficient work gets people through their shift alive.\n\nDefeat Delta Mining Drone ×8 in Extraction Zone Delta. Defeat Delta Assault Drone ×2 in Extraction Zone Delta. Then return here for Delta Recovery License.", "options": [{"text": "I will deliver a verifiable result.", "next": "exit", "action": "accept_class_trial:class_trial_omnicorp_advance"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Delta calls this an output problem.\n\nDefeat Delta Mining Drone ×8 in Extraction Zone Delta. Defeat Delta Assault Drone ×2 in Extraction Zone Delta.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The crew has safe access. That is the recovery figure I am filing. I can now issue Delta Recovery License. Choose your Advance discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_omnicorp_advance"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The crew has safe access. That is the recovery figure I am filing. Your Delta Recovery License is ready. We can choose your Advance discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10017)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_omnicorp_expert', 'class_trial_omnicorp_expert', 'npc_omnicorp_trainer_expert', 'offer', '[{"id": "offer", "text": "You are being evaluated for override authority. The reactor''s defense units are obstructing emergency access. Clear them. Do not confuse a green dashboard with a safe facility. An expert must be willing to stop a profitable process when its evidence no longer supports operation.\n\nDefeat Titan Assembly Drone ×10 in Skybridge Reactor. Defeat Titan Assembly Sentinel ×4 in Skybridge Reactor. Then return here for Reactor Override Key.", "options": [{"text": "I will deliver a verifiable result.", "next": "exit", "action": "accept_class_trial:class_trial_omnicorp_expert"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "You are being evaluated for override authority.\n\nDefeat Titan Assembly Drone ×10 in Skybridge Reactor. Defeat Titan Assembly Sentinel ×4 in Skybridge Reactor.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "Access is restored and the audit trail is intact. Your override key is approved. I can now issue Reactor Override Key. Choose your Expert discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_omnicorp_expert"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "Access is restored and the audit trail is intact. Your override key is approved. Your Reactor Override Key is ready. We can choose your Expert discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10018)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_omnicorp_master', 'class_trial_omnicorp_master', 'npc_omnicorp_trainer_master', 'offer', '[{"id": "offer", "text": "The board suggests exporting the failing cores. That would export the casualties as well. Contain the sentinel units and proto cores here, on our own ground. Return with the record. This mandate will give you authority, and a liability you may never hide in somebody else''s account.\n\nDefeat Titan Assembly Sentinel ×16 in Skybridge Reactor. Defeat Titan Proto Core ×6 in Skybridge Reactor. Then return here for OmniCorp Executive Mandate.", "options": [{"text": "I will deliver a verifiable result.", "next": "exit", "action": "accept_class_trial:class_trial_omnicorp_master"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The board suggests exporting the failing cores.\n\nDefeat Titan Assembly Sentinel ×16 in Skybridge Reactor. Defeat Titan Proto Core ×6 in Skybridge Reactor.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The failure was contained here. Your mandate records a decision we are prepared to stand behind. I can now issue OmniCorp Executive Mandate. Choose your Master discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_omnicorp_master"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The failure was contained here. Your mandate records a decision we are prepared to stand behind. Your OmniCorp Executive Mandate is ready. We can choose your Master discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10019)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_shard_base', 'class_trial_shard_base', 'npc_shard_class_trainer', 'offer', '[{"id": "offer", "text": "Power does not make the forest yours. Listen first. The barklings have turned on the paths used by our seed keepers. Still their violence and return to the Sanctum. I will entrust you with a listening shard. The calling you choose must leave room for voices other than your own.\n\nDefeat Forest Barkling ×5 in Glowvine Forest. Then return here for Listening Shard.", "options": [{"text": "I will listen, and act.", "next": "exit", "action": "accept_class_trial:class_trial_shard_base"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Power does not make the forest yours.\n\nDefeat Forest Barkling ×5 in Glowvine Forest.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The seed keepers can pass. Hold the shard gently; learning to listen has only begun. I can now issue Listening Shard. Choose your Base discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_shard_base"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The seed keepers can pass. Hold the shard gently; learning to listen has only begun. Your Listening Shard is ready. We can choose your Base discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10020)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_shard_advance', 'class_trial_shard_advance', 'npc_shard_trainer_advance', 'offer', '[{"id": "offer", "text": "The swamp remembers every wound, but memory alone cannot shelter a traveler. Creepers and titans now hold the root paths. Open them for the caretakers. Bring your account back to me; I will help you hear what survival has changed in you.\n\nDefeat Shardroot Creeper ×8 in Shardroot Swamp. Defeat Shardroot Titan ×2 in Shardroot Swamp. Then return here for Rootmemory Votive.", "options": [{"text": "I will listen, and act.", "next": "exit", "action": "accept_class_trial:class_trial_shard_advance"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The swamp remembers every wound, but memory alone cannot shelter a traveler.\n\nDefeat Shardroot Creeper ×8 in Shardroot Swamp. Defeat Shardroot Titan ×2 in Shardroot Swamp.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The root paths are open. Your votive remembers the people who can use them again. I can now issue Rootmemory Votive. Choose your Advance discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_shard_advance"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The root paths are open. Your votive remembers the people who can use them again. Your Rootmemory Votive is ready. We can choose your Advance discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10021)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_shard_expert', 'class_trial_shard_expert', 'npc_shard_trainer_expert', 'offer', '[{"id": "offer", "text": "The altar''s defenders strike at the people trying to mend it. Some call that a holy judgment. I call it another wound. End the hostile guardians'' hold over the approach. Return to Sanctum. I need a witness who sees suffering clearly, even when it contradicts a comforting story.\n\nDefeat Titan Forge Automaton ×10 in Heartwood Altar. Defeat Aethel Behemoth ×4 in Heartwood Altar. Then return here for Heartwood Witness Stone.", "options": [{"text": "I will listen, and act.", "next": "exit", "action": "accept_class_trial:class_trial_shard_expert"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The altar''s defenders strike at the people trying to mend it.\n\nDefeat Titan Forge Automaton ×10 in Heartwood Altar. Defeat Aethel Behemoth ×4 in Heartwood Altar.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "You named the wound and made room to mend it. The witness stone carries that truth. I can now issue Heartwood Witness Stone. Choose your Expert discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_shard_expert"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "You named the wound and made room to mend it. The witness stone carries that truth. Your Heartwood Witness Stone is ready. We can choose your Expert discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10022)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_shard_master', 'class_trial_shard_master', 'npc_shard_trainer_master', 'offer', '[{"id": "offer", "text": "We will leave this altar to children who did not make its scars. Push back the beasts keeping our keepers outside. Do not offer me a claim of divine favor. Offer them a place they can enter safely. That is the vow this reliquary will hold.\n\nDefeat Aethel Behemoth ×16 in Heartwood Altar. Defeat Sunken Aethel Leviathan ×6 in Heartwood Altar. Then return here for Sanctum Keeper Reliquary.", "options": [{"text": "I will listen, and act.", "next": "exit", "action": "accept_class_trial:class_trial_shard_master"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "We will leave this altar to children who did not make its scars.\n\nDefeat Aethel Behemoth ×16 in Heartwood Altar. Defeat Sunken Aethel Leviathan ×6 in Heartwood Altar.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "Those who follow us will have a safe approach. The reliquary holds your vow to keep listening. I can now issue Sanctum Keeper Reliquary. Choose your Master discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_shard_master"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "Those who follow us will have a safe approach. The reliquary holds your vow to keep listening. Your Sanctum Keeper Reliquary is ready. We can choose your Master discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10023)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_legion_base', 'class_trial_legion_base', 'npc_legion_class_trainer', 'offer', '[{"id": "offer", "text": "Stand here, where I can see your footing. The dune scavengers are threatening our water runners. Clear the outskirts, then return to the fortress. I train people for a place in the formation, not a lonely death in the sand. Earn your knot, and we will choose how you serve beside us.\n\nDefeat Dune Scavenger ×5 in Dune Outskirts. Then return here for Valka''s Formation Knot.", "options": [{"text": "I will earn my place.", "next": "exit", "action": "accept_class_trial:class_trial_legion_base"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Stand here, where I can see your footing.\n\nDefeat Dune Scavenger ×5 in Dune Outskirts.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The water runners are back. Tie the knot yourself. You have a place beside us. I can now issue Valka''s Formation Knot. Choose your Base discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_legion_base"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The water runners are back. Tie the knot yourself. You have a place beside us. Your Valka''s Formation Knot is ready. We can choose your Base discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10024)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_legion_advance', 'class_trial_legion_advance', 'npc_legion_trainer_advance', 'offer', '[{"id": "offer", "text": "The standard is useless if nobody makes it through the badlands beneath it. Ash hounds and brutes are harrying our march. Clear them and report to the fortress. I will judge your advance by the ground the next formation can safely cross.\n\nDefeat Ash Hound ×8 in Scorched Badlands. Defeat Badland Brute ×2 in Scorched Badlands. Then return here for Marchwarden Standard Tab.", "options": [{"text": "I will earn my place.", "next": "exit", "action": "accept_class_trial:class_trial_legion_advance"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "The standard is useless if nobody makes it through the badlands beneath it.\n\nDefeat Ash Hound ×8 in Scorched Badlands. Defeat Badland Brute ×2 in Scorched Badlands.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The march can continue. This tab belongs on a standard carried with others. I can now issue Marchwarden Standard Tab. Choose your Advance discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_legion_advance"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The march can continue. This tab belongs on a standard carried with others. Your Marchwarden Standard Tab is ready. We can choose your Advance discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10025)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_legion_expert', 'class_trial_legion_expert', 'npc_legion_trainer_expert', 'offer', '[{"id": "offer", "text": "Every empty place in formation has a name. The canyon''s machines are making more of them. Clear the drone ranks and their sentinels. Bring the record back. An expert sees a missing fighter before they see a convenient gap in the roster.\n\nDefeat Titan Assembly Drone ×10 in Forge Canyon Depths. Defeat Titan Assembly Sentinel ×4 in Forge Canyon Depths. Then return here for Rollkeeper Steel Token.", "options": [{"text": "I will earn my place.", "next": "exit", "action": "accept_class_trial:class_trial_legion_expert"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Every empty place in formation has a name.\n\nDefeat Titan Assembly Drone ×10 in Forge Canyon Depths. Defeat Titan Assembly Sentinel ×4 in Forge Canyon Depths.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The work crews have returned to the rolls. Keep this token where you can feel its weight. I can now issue Rollkeeper Steel Token. Choose your Expert discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_legion_expert"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The work crews have returned to the rolls. Keep this token where you can feel its weight. Your Rollkeeper Steel Token is ready. We can choose your Expert discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10026)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "quest_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_class_trial_legion_master', 'class_trial_legion_master', 'npc_legion_trainer_master', 'offer', '[{"id": "offer", "text": "Our elders promised a home beyond the march. It cannot be a fortress that devours its builders. Break the sentinels and proto cores controlling the canyon approach. Return to Kaelen. Carry this hearth standard as a duty to the living, as well as to the names we remember.\n\nDefeat Titan Assembly Sentinel ×16 in Forge Canyon Depths. Defeat Titan Proto Core ×6 in Forge Canyon Depths. Then return here for Starforged Hearth Standard.", "options": [{"text": "I will earn my place.", "next": "exit", "action": "accept_class_trial:class_trial_legion_master"}, {"text": "I need time to prepare.", "next": "exit", "action": "exit"}]}, {"id": "progress", "text": "Our elders promised a home beyond the march.\n\nDefeat Titan Assembly Sentinel ×16 in Forge Canyon Depths. Defeat Titan Proto Core ×6 in Forge Canyon Depths.\nYour record is not complete yet. You may leave and return; completed targets remain recorded.", "options": [{"text": "Review my field record.", "next": "exit", "action": "open_quest_board"}, {"text": "I will return when it is done.", "next": "exit", "action": "exit"}]}, {"id": "report", "text": "The approach is ours again. Raise the hearth standard for a home people can live in. I can now issue Starforged Hearth Standard. Choose your Master discipline after the record is secured.", "options": [{"text": "Submit the field record.", "next": "exit", "action": "claim_class_trial:class_trial_legion_master"}, {"text": "Let me review it first.", "next": "exit", "action": "exit"}]}, {"id": "certified", "text": "The approach is ours again. Raise the hearth standard for a home people can live in. Your Starforged Hearth Standard is ready. We can choose your Master discipline now. If the proof was misplaced, I can reissue it from your completed record.", "options": [{"text": "Choose my class.", "next": "exit", "action": "open_class_change"}, {"text": "I need time to choose.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10027)
on conflict (dialog_id) do update set "quest_id"=excluded."quest_id", "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";
insert into public.dialogs ("dialog_id", "npc_id", "start_node", "nodes", "source_file", "sort_order") values ('dialog_axiom_promotion', 'npc_class_advisor', 'base', '[{"id": "base", "text": "Axiom here. Your first discipline is now yours. Open Profile: your new skills are already learned, and your class bonuses now contribute to your attributes. Try a skill that suits your party role before your next hunt.", "options": [{"text": "Show my new skills.", "next": "exit", "action": "open_profile_skills"}, {"text": "Review my attributes.", "next": "exit", "action": "open_profile_stats"}, {"text": "I will review them later.", "next": "exit", "action": "exit"}]}, {"id": "advance", "text": "You have advanced, and your earlier training stays with you. Profile shows the new class bonuses and learned skills. Review your active skill loadout; knowing a skill and bringing it into a battle are separate choices.", "options": [{"text": "Show my new skills.", "next": "exit", "action": "open_profile_skills"}, {"text": "Review my attributes.", "next": "exit", "action": "open_profile_stats"}, {"text": "I will review them later.", "next": "exit", "action": "exit"}]}, {"id": "expert", "text": "Expertise gives you more choices, not a reason to stop checking them. Compare your new bonuses in Profile, inspect each learned skill, and make room for the tools your current party needs.", "options": [{"text": "Show my new skills.", "next": "exit", "action": "open_profile_skills"}, {"text": "Review my attributes.", "next": "exit", "action": "open_profile_stats"}, {"text": "I will review them later.", "next": "exit", "action": "exit"}]}, {"id": "master", "text": "Mastery does not erase the path that brought you here. Your full class history, new skills, and accumulated bonuses are in Profile. Review your loadout and remaining stat points before you lead your next expedition.", "options": [{"text": "Show my new skills.", "next": "exit", "action": "open_profile_skills"}, {"text": "Review my attributes.", "next": "exit", "action": "open_profile_stats"}, {"text": "I will review them later.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_quests.json', 10028)
on conflict (dialog_id) do update set "npc_id"=excluded."npc_id", "start_node"=excluded."start_node", "nodes"=excluded."nodes", "source_file"=excluded."source_file", "sort_order"=excluded."sort_order";

